        private Creature(string name, byte code, GameVersion gameVersion, Faction faction, int tier, CreatureInfo info, byte? baseCreatureCode = null, Dictionary<GameVersion, CreatureInfo>? versionInfo = null, Building? dwelling = null)
            : base(name, code, gameVersion)
        {
            this.Faction = faction;
            this.Tier = tier;
            this.Info = info;
            this.VersionInfo = versionInfo ?? new Dictionary<GameVersion, CreatureInfo>();
            this.BaseCreatureCode = baseCreatureCode;
            this.Dwelling = dwelling;
        }

        private Creature(string name, byte code, Faction faction, int tier, CreatureInfo info, byte? baseCreatureCode = null, Dictionary<GameVersion, CreatureInfo>? versionInfo = null, Building? dwelling = null)
            : this(name, code, GameVersion.RestorationOfErathia, faction, tier, info, baseCreatureCode, versionInfo, dwelling)
        {
        }

        public static IReadOnlyList<Creature> All => GetAll<Creature>();

        public int Tier { get; }

        public Faction Faction { get; }

        /// <summary>Gets the baseline stats, valid from the original game until the first entry of <see cref="VersionInfo"/>.</summary>
        public CreatureInfo Info { get; }

        /// <summary>Gets the stats that replace <see cref="Info"/> from the given game version onwards, until a later entry replaces them in turn.</summary>
        public IReadOnlyDictionary<GameVersion, CreatureInfo> VersionInfo { get; }

        public byte? BaseCreatureCode { get; }

        /// <summary>
        /// Gets the building of its castle that recruits the creature: the dwelling of a creature, the upgraded dwelling of an upgraded
        /// creature, or null for a creature no castle recruits (the neutral creatures, and the Cove's Sea Dog).
        /// </summary>
        public Building? Dwelling { get; }

        public static IReadOnlyList<Creature> ForFaction(Faction faction) => All.Where(c => c.Faction == faction).ToList();

        public static Creature? FromByte(byte code) => FromCode<Creature>(code);

        /// <summary>
        /// Returns the name of the creature with the given code, or words for one this editor does not know (from a mod, say).
        /// </summary>
        public static string NameOf(byte code) => FromByte(code)?.Name ?? $"Unknown creature {code}";

        /// <summary>Gets the stats of this creature as they are in savefiles written by the given game version.</summary>
        public CreatureInfo GetInfo(GameVersion version)
        {
            var info = this.Info;
            var applied = GameVersion.Unknown;

            foreach (var (since, versionInfo) in this.VersionInfo)
            {
                if (since <= version && since >= applied)
                {
                    info = versionInfo;
                    applied = since;
                }
            }

            return info;
        }
    }
}
